package com.example.starter.incident;

/**
 * 事件状态机：REPORTED → COMMANDING → CONTAINED → RESOLVED → CLOSED。
 * 只允许沿箭头前进一步，不允许跳转或回退；REPORTED → COMMANDING 仅能通过接管完成。
 */
public enum IncidentStatus {

    /** 已上报，尚无指挥人。 */
    REPORTED,

    /** 已接管，指挥人处置中。 */
    COMMANDING,

    /** 已控制。 */
    CONTAINED,

    /** 已解决，可由当前指挥人关闭。 */
    RESOLVED,

    /** 已关闭，终态，禁止任何写入。 */
    CLOSED;

    /**
     * 返回当前状态经状态变更接口可到达的下一状态；不可变更时返回 null。
     */
    public IncidentStatus next() {
        return switch (this) {
            case COMMANDING -> CONTAINED;
            case CONTAINED -> RESOLVED;
            case RESOLVED -> CLOSED;
            default -> null;
        };
    }
}

package com.example.starter.incident;

/**
 * 遏制逾期升级记录状态。
 * OPEN：逾期未遏制，待当前指挥人确认；
 * ACKNOWLEDGED：当前指挥人已提交处置说明确认，永久保留；
 * CANCELLED：事件进入 CONTAINED 时仍 OPEN 的记录被原子取消。
 * 状态只能 OPEN → ACKNOWLEDGED 或 OPEN → CANCELLED，不允许回退。
 */
public enum EscalationStatus {

    /** 逾期未遏制，待当前指挥人确认。 */
    OPEN,

    /** 已被当前指挥人确认，记录确认人与确认 UTC 时刻。 */
    ACKNOWLEDGED,

    /** 事件进入 CONTAINED 时原子取消；已确认记录不会进入此状态。 */
    CANCELLED
}

