package com.example.starter.incident.ladder;

/**
 * 升级阶梯等级变更类型，对应 incident_ladder_history.change_type。
 * 历史行 append-only、不可变；后续阈值版本修订不回写任何历史行。
 */
public enum LadderChangeType {

    /** 首次登记风险分数并入阶梯；from_level/from_score 为空，to_level 为按阈值计算的初始等级。 */
    INIT,

    /** 批量分数更新被接受但等级未变化（from_level = to_level，分数本身形成不可变证据）。 */
    SCORE_UPDATE,

    /** 分数达到更高阈值触发的自动提升，可一次跨多级；刷新冷却起点与最近升级操作人。 */
    AUTO_ESCALATE,

    /** 人工确认的降级，只能逐级向下（to_level = from_level - 1）；不刷新冷却起点。 */
    DEMOTE
}

package com.example.starter.incident.ladder;

import java.time.Instant;
import java.util.List;

/**
 * 升级阈值配置版本实体，对应 escalation_threshold_versions 表，行内容不可变。
 * thresholds 固定为 5 个非负分数门槛，下标 0 对应 1 级，必须严格递增；
 * 等级判定：L(score) = max({1} ∪ {i | score ≥ thresholds[i-1]})，即入阶梯至少 1 级。
 * cooldownMinutes 为降级冷却分钟数：距最近升级必须严格超过该时长才允许降级。
 */
public record ThresholdVersion(
        long id,
        String versionKey,
        List<Long> thresholds,
        int cooldownMinutes,
        String createdBy,
        Instant createdAt) {

    /** 阶梯固定级数。 */
    public static final int LEVELS = 5;

    /** 冷却分钟数合法范围（含端点）：0 表示无冷却，上限 527040 = 366 天。 */
    public static final int COOLDOWN_MIN = 0;

    /** 冷却分钟数合法上限（366 天）。 */
    public static final int COOLDOWN_MAX = 366 * 24 * 60;
}

